-- DROP TEXT SEARCH with several names: names resolve and are checked in
-- order, then drop together under one dependency check.
create text search dictionary d1 (template = simple);
create text search dictionary d2 (template = simple, stopwords = english);
create text search configuration c1 (copy = english);
create text search configuration c2 (copy = simple);
alter text search configuration c1 alter mapping for asciiword with d1;
alter text search configuration c2 alter mapping for asciiword with d2, d1;
drop text search dictionary d1, d2;
drop text search dictionary if exists nope, d1, nope2;
drop text search dictionary d1, nope;
drop text search dictionary public.nope;
drop text search dictionary nosuch.nope;
drop text search dictionary if exists nosuch.nope, d1;
drop text search configuration c1, c2, c1;
select cfgname from pg_ts_config where cfgname like 'c_' order by 1;
drop text search dictionary d1, d2 cascade;
select dictname from pg_ts_dict where dictname like 'd_' order by 1;
create text search template t1 (lexize = dsimple_lexize);
create text search template t2 (init = dsimple_init, lexize = dsimple_lexize);
create text search dictionary d3 (template = t1);
create text search dictionary d4 (template = t2);
drop text search template t1, t2;
drop text search template t1, t2 restrict;
drop text search template t2, t1 cascade;
create text search parser p1 (start = prsd_start, gettoken = prsd_nexttoken, end = prsd_end, lextypes = prsd_lextype);
create text search parser p2 (start = prsd_start, gettoken = prsd_nexttoken, end = prsd_end, lextypes = prsd_lextype);
create text search configuration c3 (parser = p1);
create text search configuration c4 (parser = p2);
drop text search parser p1, p2;
drop text search parser p1, p2 cascade;
drop text search parser if exists p1, p2;
drop text search configuration english, simple;
drop text search dictionary simple;
drop text search parser default;
drop text search configuration if exists ;
drop text search configuration a,;
create role tsr;
create text search dictionary d5 (template = simple);
set role tsr;
drop text search dictionary if exists nope, d5;
reset role;
drop text search dictionary d5, d5;
drop role tsr;
